class Solution {
public:
    int minimumDifference(vector<int>& nums) {
        int n = (int)nums.size() / 2;
        long long total = 0;
        for (int x : nums) total += x;

        vector<vector<long long>> left(n + 1), right(n + 1);

        for (int mask = 0; mask < (1 << n); mask++) {
            long long s = 0;
            int cnt = __builtin_popcount((unsigned)mask);
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) s += nums[i];
            }
            left[cnt].push_back(s);
        }
        for (int mask = 0; mask < (1 << n); mask++) {
            long long s = 0;
            int cnt = __builtin_popcount((unsigned)mask);
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) s += nums[n + i];
            }
            right[cnt].push_back(s);
        }

        for (int k = 0; k <= n; k++) {
            sort(right[k].begin(), right[k].end());
        }

        long long ans = LLONG_MAX;
        for (int k = 0; k <= n; k++) {
            auto &R = right[n - k];
            for (long long s1 : left[k]) {
                long long want = total / 2 - s1;
                auto it = lower_bound(R.begin(), R.end(), want);
                if (it != R.end()) {
                    long long s2 = *it;
                    long long sum1 = s1 + s2;
                    long long diff = llabs(2 * sum1 - total);
                    if (diff < ans) ans = diff;
                }
                if (it != R.begin()) {
                    --it;
                    long long s2 = *it;
                    long long sum1 = s1 + s2;
                    long long diff = llabs(2 * sum1 - total);
                    if (diff < ans) ans = diff;
                }
            }
        }
        return (int)ans;
    }
};
